                continue;
            }

            if (strncmp(s, "spi=", 4) == 0) {
                s += 4;
                len = scan_u32(s, &spi, mask ? &spi_mask : NULL);
                if (len == 0) {
                    return -EINVAL;
                }
                s += len;
                continue;
            }

            if (strncmp(s, "si=", 3) == 0) {
                s += 3;
                len = scan_u8(s, &si, mask ? &si_mask : NULL);
                if (len == 0) {
                    return -EINVAL;
