                                mask ? &smask.context[0] : NULL);
                if (len == 0) {
                    return -EINVAL;
                }
                s += len;
                continue;
            }

            if (strncmp(s, "c2=", 3) == 0) {
                s += 3;
                len = scan_be32(s, &skey.context[1],
                                mask ? &smask.context[1] : NULL);
